import { mock } from 'node:test';
import path from 'node:path';
const fs = await import('node:fs/promises');
const root = await fs.realpath(await fs.mkdtemp('/tmp/ship-choosing-cleanup-'));
const claim = path.join(root, 'state.json');
let fault = true;
let ran1 = false;
let ran2 = false;
const results = { root, pid: process.pid };
mock.module('node:fs/promises', { namedExports: { ...fs,
  mkdir: async (p, ...args) => {
    const value = await fs.mkdir(p, ...args);
    if (fault && String(p).startsWith(root) && String(p).includes('.pubq-')) {
      fault = false;
      await fs.chmod(root, 0o555);
    }
    return value;
  },
} });
const { withPublishMutex } = await import('/Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/lock-pubmutex.js');
try {
  await withPublishMutex(claim, claim, () => false, async () => { ran1 = true; }).catch(e => { results.firstError = { message:e.message, code:e.code }; });
  results.firstRan = ran1;
  await fs.chmod(root, 0o755);
  results.afterRestore = await fs.readdir(root);
  const start = Date.now();
  await withPublishMutex(claim, claim, () => Date.now() - start >= 250, async () => { ran2 = true; }).catch(e => { results.secondError = e.message; });
  results.secondElapsed = Date.now() - start;
  results.secondRan = ran2;
  results.afterSecond = await fs.readdir(root);
  // The process and restored directory remain healthy: only deletion of our
  // exact orphaned choosing marker allows this same key to progress again.
  for (const name of results.afterSecond.filter(x => x.includes('.pubc-'))) await fs.rm(path.join(root, name), { recursive:true, force:true });
  const deadline = Date.now() + 250;
  results.afterManualOrphanRemoval = await withPublishMutex(claim, claim, () => Date.now() >= deadline, async () => 'entered');
  await fs.writeFile('/tmp/codex-tool-runs/svton/script-lock-closure-20261004/choosing-cleanup-result.json', JSON.stringify(results, null, 2));
  console.log(JSON.stringify(results, null, 2));
} finally {
  await fs.chmod(root, 0o755).catch(()=>{});
  await fs.rm(root, { recursive: true, force: true });
}

import { spawn } from 'node:child_process';
import { createServer } from 'node:net';
import { createHash } from 'node:crypto';
import { mkdtemp, mkdir, chmod, rm, readFile, writeFile, readdir, realpath } from 'node:fs/promises';
import path from 'node:path';
const root=await realpath(await mkdtemp('/tmp/ship-reg03-full-permission-'));
const registry=path.join(root,'registry');
await mkdir(registry);
const file=path.join(root,'state.json');
await writeFile(file,'0');
const key=file;
const claim=path.join(registry,`${createHash('sha256').update(key).digest('hex').slice(0,20)}.json`);
const firstPort=49152+(createHash('sha256').update([key,'0'].join('\u0000')).digest().readUInt32BE(0)%16383);
const mod='file:///Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/file-lock.js';
const children=[];
function child(name,pausePublish) {
 const c=spawn(process.execPath,['--experimental-test-module-mocks','--input-type=module','-e',`
import { mock } from 'node:test';
const real=await import('node:fs/promises');
const prefix='/var/tmp/shipkit-lock-ports';
const dest=${JSON.stringify(registry)};
const map=p=>typeof p==='string'&&p.startsWith(prefix)?dest+p.slice(prefix.length):p;
let resume,release,paused=false;
process.on('message',m=>{if(m==='resume')resume?.();if(m==='release')release?.();if(m==='exit')process.exit(0);});
const wrap={...real};
for(const k of ['access','mkdir','readFile','readdir','rm','writeFile'])wrap[k]=(...a)=>real[k](map(a[0]),...a.slice(1));
wrap.rename=async(a,b)=>{
 if(${JSON.stringify(pausePublish)}&&!paused&&String(b).startsWith(prefix)&&String(b).endsWith('.json')){
  paused=true;const gate=new Promise(r=>resume=r);
  process.send({event:'before-publish',port:JSON.parse(await real.readFile(map(a),'utf8')).port});
  await gate;
 }
 return real.rename(map(a),map(b));
};
mock.module('node:fs/promises',{namedExports:wrap});
const {withFileLock}=await import(${JSON.stringify(mod)});
try{
 await withFileLock(${JSON.stringify(file)},async()=>{
  const gate=new Promise(r=>release=r);
  const old=Number(await real.readFile(${JSON.stringify(file)},'utf8'));
  const port=JSON.parse(await real.readFile(${JSON.stringify(claim)},'utf8')).port;
  process.send({event:'entered',old,port,pid:process.pid});
  await gate;
  await real.writeFile(${JSON.stringify(file)},String(old+1));
 },{timeoutMs:15000});
 process.send({event:'finished'});
}catch(e){process.send({event:'error',message:e.message,code:e.code});}
`],{stdio:['ignore','ignore','inherit','ipc']});
 const events=[];
 const exited=new Promise(r=>c.on('exit',r));
 c.on('message',e=>events.push({...e,at:Date.now()}));
 children.push({c,exited});
 return {c,events,wait:async event=>{const end=Date.now()+5000;while(Date.now()<end){const found=events.find(e=>e.event===event);if(found)return found;await new Promise(r=>setTimeout(r,10));}return null;}};
}
const blocker=createServer(s=>s.destroy());
try{
 await new Promise((r,j)=>{blocker.once('error',j);blocker.listen(firstPort,'127.0.0.1',r);});
 const b=child('B',true);
 const paused=await b.wait('before-publish');
 if(!paused)throw new Error('B not parked '+JSON.stringify(b.events));
 await new Promise(r=>blocker.close(r));
 await chmod(registry,0o333);
 const readError=await readdir(registry).then(()=>null,e=>e.code);
 const a=child('A',false);
 await new Promise(r=>setTimeout(r,300));
 const aDuringFault=a.events.find(e=>e.event==='entered')??null;
 await chmod(registry,0o755);
 b.c.send('resume');
 const bEntered=await b.wait('entered');
 if(!bEntered)throw new Error('B did not resume '+JSON.stringify(b.events));
 await new Promise(r=>setTimeout(r,150));
 const aBeforeBRelease=a.events.find(e=>e.event==='entered')??null;
 const overlapping=Boolean(aBeforeBRelease);
 const mapped=JSON.parse(await readFile(claim,'utf8')).port;
 b.c.send('release'); await b.wait('finished');
 const aEntered=await a.wait('entered');
 if(!aEntered)throw new Error('A did not recover '+JSON.stringify(a.events));
 a.c.send('release'); await a.wait('finished');
 const evidence={root,file,registry,readError,firstPort,paused,aDuringFault,overlapping,mapped,a:a.events,b:b.events,final:Number(await readFile(file,'utf8')),expectedFinal:2};
 await writeFile('/tmp/codex-tool-runs/svton/script-lock-closure-20261004/full-readdir-permissions-evidence.json',JSON.stringify(evidence,null,2));
 console.log(JSON.stringify(evidence,null,2));
}finally{
 await chmod(registry,0o755).catch(()=>{});
 blocker.close();
 for(const{c}of children)c.send('exit');
 await Promise.all(children.map(x=>x.exited));
 await rm(root,{recursive:true,force:true});
}

import { mkdtemp, chmod, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { withPublishMutex } from '/Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/lock-pubmutex.js';
const root=await mkdtemp('/tmp/ship-reg03-pubmutex-cleanup-');
const claim=path.join(root,'claim.json');
try {
 const initial=await withPublishMutex(claim,claim,()=>false,async()=>{await chmod(root,0o555);return 'first';}).then(value=>({value}),e=>({message:e.message,code:e.code}));
 await chmod(root,0o755);
 let callbackRan=false;
 const deadline=Date.now()+100;
 const later=withPublishMutex(claim,claim,()=>Date.now()>=deadline,async()=>{callbackRan=true;return 'recovered';});
 const recovered=await Promise.race([later.then(value=>({value}),e=>({message:e.message,code:e.code})),new Promise(r=>setTimeout(()=>r({stillPending:true}),350))]);
 const evidence={initial,recovered,callbackRan,expired:true};
 await writeFile('/tmp/codex-tool-runs/svton/script-lock-closure-20261004/cleanup-recovery-evidence.json',JSON.stringify(evidence,null,2));
 console.log(JSON.stringify(evidence,null,2));
} finally {
 await chmod(root,0o755).catch(()=>{});
 await rm(root,{recursive:true,force:true});
}

import { mock } from 'node:test';
import { createHash } from 'node:crypto';
import path from 'node:path';
const fs = await import('node:fs/promises');
const net = await import('node:net');
const root = await fs.realpath(await fs.mkdtemp('/tmp/ship-retry-deadline-'));
const file = path.join(root, 'state.json');
const hash = createHash('sha256').update(file).digest('hex');
const claim = path.join('/var/tmp/shipkit-lock-ports', hash.slice(0, 20) + '.json');
const { claimPort } = await import('file:///Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/lock-registry.js');
const port = await claimPort(file);
const holder = net.createServer(s => s.end(`shiplock:${process.pid}:${hash.slice(0,8)}\n`));
await new Promise((r, reject) => { holder.once('error', reject); holder.listen(port, '127.0.0.1', r); });
let calls = 0;
let start;
let pausedAtMs = null;
mock.module('node:net', { namedExports: { ...net, createServer: (...args) => {
  const s = net.createServer(...args);
  const listen = s.listen.bind(s);
  s.listen = (...params) => {
    calls++;
    if (calls === 2) {
      pausedAtMs = performance.now() - start;
      // Async scheduling delay before the REAL second listen. Holder stays live.
      setTimeout(() => listen(...params), 300);
      return s;
    }
    return listen(...params);
  };
  return s;
} } });
const { withFileLock, heldToken } = await import('file:///Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/file-lock.js');
let callbackRan = false;
let error = null;
try {
  start = performance.now();
  try { await withFileLock(file, () => { callbackRan = true; }, { timeoutMs: 150 }); }
  catch (e) { error = e.message; }
  const returnedAtMs = performance.now() - start;
  const result = { timeoutMs: 150, pauseMs: 300, callbackRan, error, returnedAtMs, pausedAtMs, calls, token: heldToken(file),
    method: 'First listen really fails against own live holder; only second listen is delayed 300ms before invoking the original. Real probe, live banner and bind failure; no syscall result is faked.' };
  await fs.writeFile('/tmp/codex-tool-runs/svton/script-lock-closure-20261004/retry-bind-result.json', JSON.stringify(result, null, 2));
  console.log(JSON.stringify(result));
} finally {
  await new Promise(r => holder.close(r));
  await fs.rm(claim, { force: true });
  await fs.rm(root, { recursive: true, force: true });
}

import { mock } from 'node:test';
import { createHash } from 'node:crypto';
import path from 'node:path';
const mode = process.argv[2] ?? 'write';
const fs = await import('node:fs/promises');
const sleep = ms => new Promise(r => setTimeout(r, ms));
const base = '/tmp/codex-tool-runs/svton/script-lock-closure-20261004';
const root = await fs.realpath(await fs.mkdtemp('/tmp/ship-publication-deadline-'));
const file = path.join(root, 'state.json');
await fs.writeFile(file, '0');
const stem = createHash('sha256').update(file).digest('hex').slice(0, 20) + '.json';
const registry = '/var/tmp/shipkit-lock-ports';
const claim = path.join(registry, stem);
const own = n => n === stem || n.startsWith(`${stem}.pub`) || n.startsWith(`.${stem}.`);
let pausedAtMs = null;
let resumeAtMs = null;
let start = 0;
let once = true;
mock.module('node:fs/promises', { namedExports: { ...fs,
  writeFile: async (...args) => {
    const r = await fs.writeFile(...args);
    if (mode === 'write' && once && String(args[0]).includes(`.${stem}.`) && String(args[0]).endsWith('.tmp')) {
      once = false;
      pausedAtMs = performance.now() - start;
      await sleep(300);
      resumeAtMs = performance.now() - start;
    }
    return r;
  },
  rename: async (...args) => {
    if (mode === 'rename' && once && String(args[1]) === claim) {
      once = false;
      pausedAtMs = performance.now() - start;
      await sleep(300);
      resumeAtMs = performance.now() - start;
    }
    return fs.rename(...args);
  }
} });
const { withFileLock, heldToken } = await import('file:///Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/file-lock.js');
let callbackRan = false;
let error = null;
let result;
try {
  start = performance.now();
  try { await withFileLock(file, () => { callbackRan = true; }, { timeoutMs: 100 }); }
  catch (e) { error = e.message; }
  const returnedAtMs = performance.now() - start;
  const filesAtReturn = (await fs.readdir(registry)).filter(own);
  await sleep(650);
  const filesAfterDrain = (await fs.readdir(registry)).filter(own);
  const claimAfterDrain = await fs.readFile(claim, 'utf8').then(JSON.parse, () => null);
  const tokenAfterDrain = heldToken(file);
  if (pausedAtMs === null || pausedAtMs >= returnedAtMs) throw Error('Test precondition: publication pause was not reached during the timed acquisition');
  let recovered = false;
  await withFileLock(file, () => { recovered = true; }, { timeoutMs: 5000 });
  result = { mode, timeoutMs: 100, pauseMs: 300, callbackRan, error, returnedAtMs, pausedAtMs, resumeAtMs,
    filesAtReturn, filesAfterDrain, claimAfterDrain, tokenAfterDrain, recovered,
    method: 'Only a scheduling pause around a real temp write or before the original rename. All filesystem and network calls execute unchanged. Synthetic unique state file, own-key cleanup only.' };
  await fs.writeFile(`${base}/publication-${mode}-result.json`, JSON.stringify(result, null, 2));
  console.log(JSON.stringify(result));
} finally {
  for (const n of (await fs.readdir(registry)).filter(own)) await fs.rm(path.join(registry, n), { recursive: true, force: true });
  await fs.rm(root, { recursive: true, force: true });
}
